function parseArticles(xmlText) {
  const itemMatches = [...xmlText.matchAll(/<item[^>]*>([\s\S]*?)<\/item>/gi)];
  if (itemMatches.length === 0) return [];
  const articles = [];
  for (let i = 0; i < Math.min(2, itemMatches.length); i++) {
    const itemXml = itemMatches[i][1];
    const titleMatch = itemXml.match(/<title>(?:<!\[CDATA\[)?([^\]<]+)(?:\]\]>)?<\/title>/);
    const title = titleMatch ? titleMatch[1].trim() : 'Untitled';
    const linkMatch =
      itemXml.match(/<link>([^<]+)<\/link>/) ||
      itemXml.match(/<guid[^>]*isPermaLink="true"[^>]*>([^<]+)<\/guid>/) ||
      itemXml.match(/<guid[^>]*>([^<]+)<\/guid>/);
    const link = linkMatch ? linkMatch[1].trim() : '#';
    const descMatch = itemXml.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/i);
    let description = '';
    if (descMatch) {
      description = descMatch[1]
        .replace(/<[^>]+>/g, '')
        .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
        .replace(/&lt;/g, '<').replace(/&gt;/g, '>')
        .replace(/&quot;/g, '"').trim();
      if (description.length > 200) description = description.substring(0, 197) + '...';
    }
    articles.push({ title, link, description });
  }
  return articles;
}

const results = [];

for (const site of sites) {
  const siteUrl = site.rss.split('/').slice(0, 3).join('/');
  try {
    const xmlText = await this.helpers.httpRequest({
      method: 'GET',
      url: site.rss,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; RSSReader/1.0)' },
      timeout: 10000
    });
    if (!xmlText || xmlText.trim().length === 0) {
      results.push({ json: { siteName: site.name, siteUrl, articles: [], skipped: true, reason: 'empty response' } });
      continue;
    }
    const articles = parseArticles(xmlText);
    results.push({ json: { siteName: site.name, siteUrl, articles, skipped: articles.length === 0 } });
  } catch (err) {
    results.push({ json: { siteName: site.name, siteUrl, articles: [], skipped: true, reason: err.message } });
  }
}

return results;

