let html = `<div style="background: linear-gradient(135deg, #0f0c29, #302b63, #24243e); border-radius: 12px; padding: 40px 30px; text-align: center; margin-bottom: 40px; font-family: Arial, sans-serif;"><h1 style="color: #ffffff; font-size: 2.2em; margin: 0 0 8px 0; font-weight: 800; letter-spacing: 1px;">Web3 News Roundup</h1><p style="color: #a78bfa; font-size: 1.1em; margin: 0; font-weight: 500;">${dateStr}</p><p style="color: #d1d5db; font-size: 0.9em; margin-top: 12px;">Your weekly digest of the top stories.</p></div>`;

for (const site of allSites) {
  const siteName = site.siteName || 'Unknown';
  const siteUrl  = site.siteUrl  || '#';
  const articles  = Array.isArray(site.articles) ? site.articles : [];
  const skipped   = site.skipped || false;
  if (skipped || articles.length === 0) continue;

  html += `<div style="margin-bottom: 32px; padding: 20px; border-left: 4px solid #7c3aed; background: #f9f7ff; border-radius: 6px;"><h2 style="color: #4c1d95; font-size: 1.3em; margin: 0 0 14px 0; font-family: Arial, sans-serif;">📰 ${siteName}</h2><ul style="list-style: none; padding: 0; margin: 0;">`;

  for (const article of articles) {
    html += `<li style="margin-bottom: 14px; padding: 12px 14px; background: #ffffff; border-radius: 6px; box-shadow: 0 1px 4px rgba(0,0,0,0.06);"><a href="${article.link}" target="_blank" rel="noopener noreferrer" style="color: #1d4ed8; text-decoration: none; font-weight: 600; font-size: 0.97em; font-family: Arial, sans-serif; display: block; margin-bottom: 4px;">${article.title}</a>${article.description ? `<p style="color: #4b5563; font-size: 0.88em; margin: 0; font-family: Arial, sans-serif; line-height: 1.5;">${article.description}</p>` : ''}</li>`;
  }

  html += `</ul><div style="margin-top: 10px; padding-top: 10px; border-top: 1px solid #e9d5ff;"><a href="${siteUrl}" target="_blank" rel="noopener noreferrer" style="color: #7c3aed; font-size: 0.85em; font-family: Arial, sans-serif; text-decoration: none;">See more from ${siteName} →</a></div></div>`;
}

html += `<div style="border-top: 1px solid #e5e7eb; margin-top: 40px; padding-top: 20px; text-align: center; font-family: Arial, sans-serif; color: #6b7280; font-size: 0.85em;"><p>This roundup is automatically curated every Sunday, however may run more often on occasion of especially busy news weeks. All headlines link directly to their original sources.</p></div>`;

return [{ json: { postTitle, postContent: html } }];
